update t_knowledge_point set title = $kp$非冯·诺依曼结构计算机$kp$, content = $kp$目前大多数计算机仍建立在存储程序概念的基础上，但随着计算机技术的发展，也暴露出冯·诺依曼型计算机的一些缺点。现已出现一些突破冯·诺依曼结构的计算机，统称为非冯·诺依曼结构计算机，如数据驱动的数据流计算机、需求驱动的归约计算机和模式匹配驱动的智能计算机等。$kp$, section = '' where id = 21881;
update t_knowledge_point set title = $kp$计算机系统的组成与逻辑结构$kp$, content = $kp$计算机系统由硬件系统和软件系统两部分组成。硬件系统由运算器、控制器、存储器、输入设备和输出设备五大部件构成，它们通过总线互相连接。CPU、内存储器、总线等构成计算机的主机；外存储器、输入设备、输出设备构成计算机的外围设备，简称外设。$kp$, section = '' where id = 21883;
update t_knowledge_point set title = $kp$硬件五大部件与主机、外设的划分$kp$, content = $kp$硬件系统遵循冯·诺依曼提出的存储程序与程序控制原理，由运算器、控制器、存储器、输入设备、输出设备五部分组成。五大部件中，CPU、内存储器、总线等构成主机；外存储器、输入设备、输出设备构成外围设备，简称外设。$kp$, section = '' where id = 21884;
update t_knowledge_point set title = $kp$单片机与 SoC 芯片$kp$, content = $kp$把运算器、控制器、存储器、I/O 控制、接口电路全都集成在一块芯片上，这样的超大规模集成电路称为单片机。如果芯片中不仅包含微处理器，还把存储器、I/O 控制接口电路，甚至模拟电路、数字/模拟混合电路和射频电路等也集成在单个芯片中，则称为 SoC（System on Chip），国内称为片上系统或系统级芯片。单片机和 SoC 芯片大多内嵌在其他设备中作为嵌入式计算机使用，如数码相机、MP3 播放器、路由器、计算机外设、汽车、机顶盒等。全球市场份额最大的是英国 ARM 公司的 ARM 处理器，现在大部分手机和平板电脑（包括苹果 iPad）使用的都是采用 ARM 技术的微处理器。$kp$, section = '' where id = 22142;
update t_knowledge_point set title = $kp$信息、集成电路与数据库基础单选题选编$kp$, content = $kp$本条为单选题合集，题目内容覆盖信息与信息技术（信息与数据的含义、信息处理阶段、信息器官功能的扩展、信息技术的核心技术）、集成电路（分类依据、摩尔定律）、通信系统的组成与信息传输，以及信息系统与数据库（关系模型、候选键、数据库管理系统、CIMS）等基础概念。原文在关系运算题处中断，未附参考答案。$kp$, section = '' where id = 22155;
update t_knowledge_point set title = $kp$量子、光学与生物计算机$kp$, content = $kp$目前计算机几乎都使用半导体集成电路，人们也在研究基于其他材料的计算机：量子计算机建立在量子力学基础上，可以同时使用多个不同的量子态来处理和存储信息；光学计算机以光子代替电子，用光互连代替导线互连，用光硬件代替电子硬件，用光运算代替电运算；生物计算机利用蛋白质分子与周围物理化学介质的相互作用，转换开关由酶充当，程序体现在酶合成系统本身和蛋白质的结构中，预计 10～20 年后 DNA 计算机将进入实用阶段。这些技术目前还不成熟，与实际应用有很大差距。$kp$, section = '' where id = 22189;
update t_knowledge_point set title = $kp$神威·太湖之光巨型计算机$kp$, content = $kp$峰值计算速度达每秒 12.54 亿亿次，持续计算速度为每秒 9.3 亿亿次，包含 40960 个自主开发的 SW26010 处理器（每个处理器有 260 个内核），内存总容量达 1310TB。2016 年 6 月在全球超级计算机 500 强排行榜中名列第一。$kp$, section = '' where id = 22201;
update t_knowledge_point set title = $kp$第 1～4 代计算机对比$kp$, content = $kp$| 代别 | 年代 | 使用的元器件 | 软件类型 | 主要应用领域 |
| --- | --- | --- | --- | --- |
| 第 1 代 | 20 世纪 40 年代中期至 50 年代末期 | CPU：电子管；内存：磁鼓 | 机器语言和汇编语言 | 科学和工程计算 |
| 第 2 代 | 20 世纪 50 年代中后期至 60 年代中期 | CPU：晶体管；内存：磁芯 | FORTRAN、COBOL 等高级程序设计语言 | 开始广泛应用于数据处理领域 |
| 第 3 代 | 20 世纪 60 年代中期至 70 年代初期 | CPU：SSI、MSI；内存：SSI、MSI 的半导体存储器 | 操作系统、数据库管理系统等开始使用 | 科学计算、数据处理、工业控制 |
| 第 4 代 | 20 世纪 70 年代中期以来 | CPU：LSI、VLSI；内存：LSI、VLSI 的半导体存储器 | 软件开发工具和平台、分布式计算、网络软件等开始广泛使用 | 深入各行各业，家庭和个人开始使用计算机 |$kp$, section = '' where id = 22204;
update t_knowledge_point set title = $kp$冯·诺依曼计算机的逻辑结构$kp$, content = $kp$输入设备将程序和数据送入运算器与控制器；运算器与控制器从存储器读取指令和数据，运算处理后再将结果送回存储器；处理结果由输出设备输出。这里的逻辑结构指概念上（即功能上）的结构，而不是实际的物理结构。$kp$, section = '' where id = 22209;
update t_knowledge_point set title = $kp$计算机的分类与三种使用方式$kp$, content = $kp$按内部逻辑结构可分为 8 位、16 位、32 位、64 位机，单 CPU 机与多 CPU 机等。按性能和价格可分为巨型计算机、大型计算机、小型计算机（服务器）、个人计算机（台式 PC、笔记本 PC、平板电脑等）和嵌入式计算机。按使用方式，计算机可作为服务器使用，可独立使用或作为客户机使用，也可嵌入在非计算机的设备中使用。$kp$, section = '' where id = 22218;
update t_knowledge_point set title = $kp$计算机的诞生与发展$kp$, content = $kp$计算机速度不断提高、功能增加、体积缩小、成本降低、应用扩大，发展之快不断改写预测：早期 8～10 年运算速度提高十倍，而成本和体积降为原来的 1/10；20 世纪 80 年代开始，几乎每三年性能提高近四倍，成本下降一半。推动力是微电子技术的进展和计算机应用的需求。通常按主机所使用的元器件划代：第一代（约 1946—1957 年）为电子管计算机，速度几十次/秒至几万次/秒，用水银延迟线作内存、容量约千字，外设为磁鼓、纸带、卡片、磁带，用机器语言编程；第二代（约 1957—1964 年）为晶体管计算机，速度几十万次/秒，用磁芯作内存、容量十万字级，出现磁盘，用汇编语言或高级语言编程（1947 年底贝尔实验室发明晶体管）。此后进入中小规模集成电路、大规模和超大规模集成电路阶段。$kp$, section = '' where id = 22220;
update t_knowledge_point set title = $kp$按性能、用途和价格划分的计算机类型$kp$, content = $kp$按内部逻辑结构分为单处理机、多处理机（并行机）；按字长分为 16 位机、32 位机、64 位机等；按性能、用途和价格分为：

| 类型 | 用途与特点 |
| --- | --- |
| 巨型计算机（Supercomputer） | 采用大规模并行处理的体系结构，CPU 由数以百计、千计、万计的处理器组成，运算处理能力极强，速度达每秒万亿次以上，大多用于军事、科研、气象、石油勘探等领域。 |
| 大型计算机（Mainframe） | 运算速度快、存储容量大、通信联网功能完善、可靠性高、安全性好、系统软件和应用软件丰富，CPU 通常有 4、8、16、32 个甚至更多处理器；为企业或政府数据提供集中的存储、管理和处理，作为主服务器（企业级服务器）。 |
| 小型计算机（Minicomputer） | 为多个用户执行任务，但没有大型机的高性能，支持的并发用户数较少；典型应用是帮助中小企业或大型企业的一个部门完成库存管理、销售管理、文档管理等任务。 |
| 个人计算机（Personal Computer） | 以微处理器为中心的独立完整的计算机系统，价格便宜、使用方便、软件丰富，适合办公或家庭使用，通常只处理一个用户的任务，可独立使用，也可与其他计算机互连。 |
| 工作站（Workstation） | 具有高速运算能力和强大的图形处理功能，通常运行 UNIX 操作系统，特别适合工程与产品设计，SGI、SUN、HP、IBM 等公司都有此类产品。 |$kp$, section = '' where id = 22290;
update t_knowledge_point set title = $kp$巨型计算机$kp$, content = $kp$巨型计算机也称超级计算机，有极强的运算处理能力，速度达到每秒数万、数十万亿次以上；采用大规模并行处理的结构，由数以百计、千计、万计的 CPU 共同完成系统软件和应用软件的运行任务；大多用于军事、科研、气象预报、石油勘探、飞机设计模拟、生物信息处理、破解密码等领域。国外代表厂商有美国 IBM 公司、Cray 公司和日本富士通公司、NEC 公司；我国有国防科技大学的“天河一号”“天河二号”（亿亿次/秒）、江南计算技术研究所的“神威”巨型机、中科院计算所（曙光计算机公司）的“曙光”巨型计算机和联想集团公司的“深腾”巨型机。$kp$, section = '' where id = 22492;
update t_knowledge_point set title = $kp$按服务对象划分的三类计算机$kp$, content = $kp$| 类型 | 服务对象 | 应用性质 | 主要特点 | 举例 | 软件特点 |
| --- | --- | --- | --- | --- | --- |
| 个人计算机 | 直接为用户服务 | 通用 | 性能价格比高，多媒体性能好，有通用性和可扩展性 | 工作站、台式机、笔记本 | 种类多、功能丰富，用户可自行装卸 |
| 服务器 | 为其他计算机服务 | 半通用 | 吞吐率高，可用性好，有可扩展性 | 数据库服务器、Web 服务器、打印服务器（企业级、部门级等） | 实时处理和并发工作能力强，可靠性和安全性好 |
| 嵌入式计算机 | 为其他设备服务 | 专用 | 价格便宜，功耗低，实时处理，软件固化，扩展性差 | 路由器、数码相机、MP3 播放器 | 功能专用、单一，结构紧凑，固化在芯片中，不易修改和扩充 |$kp$, section = '' where id = 22541;
update t_knowledge_point set title = $kp$按逻辑结构与性能用途的分类$kp$, content = $kp$按内部逻辑结构分为 16 位机、32 位机、64 位计算机等；按计算机的性能、用途和价格分为巨型计算机、大型计算机、小型计算机、个人计算机和嵌入式计算机。$kp$, section = '' where id = 24136;
update t_knowledge_point set title = $kp$光计算机与生物计算机$kp$, content = $kp$英国女王大学的 Anatoly Zayats 教授是光计算机项目的负责人；奥林巴斯光学工业公司开发出了生物计算机。$kp$, section = '' where id = 25138;
update t_knowledge_point set title = $kp$计算机的应用领域$kp$, content = $kp$科学计算（工程设计、地震预测、气象预测、航天技术）；数据处理与信息管理（企业管理、物流管理、数据统计、图书与情报检索）；生产自动化；人工智能。$kp$, section = '' where id = 25193;
update t_knowledge_point set title = $kp$计算机的特点与存储程序控制原理$kp$, content = $kp$1946 年美国宾夕法尼亚大学研制出第一台数字电子计算机 ENIAC；现在学术界和工业界已不再使用“第 X 代计算机”的说法。计算机是一种信息处理工具，其智能化以知识处理为核心。存储程序控制：计算机的工作由程序控制，程序是命令序列；程序（指令）和数据均以二进制编码表示，存放在存储器中；存放的指令和数据按地址存取；指令由 CPU 一条一条顺序执行。冯·诺依曼提出三条设计原理：① 计算机使用二进制；② 计算机自动工作的原因是存储程序控制；③ 计算机分为运算器、控制器、存储器、输入设备、输出设备五个基本组成部分。任务执行过程：启动时把程序和数据从辅存送入内存，CPU 从内存取出指令和数据，按指令运算并把结果送回内存，需要时再送到辅存长期保存。使用二进制的原因：运算规则简单，能实现逻辑运算与数学运算的统一，物理实现简单。性能指标一般指 CPU 的性能、运算速度（MIPS 为百万条定点指令/秒，MFLOPS 为百万条浮点指令/秒）、存储容量（主要指内存容量）、存储周期、字长、主频和内核数量；内存容量影响计算机性能，但不影响 CPU 的性能。$kp$, section = '' where id = 25194;
update t_knowledge_point set title = $kp$计算机的分代与应用模式$kp$, content = $kp$第 1 代：CPU 用电子管，内存用磁鼓，使用机器语言或汇编语言，应用于科学和工程计算；第 2 代：CPU 用晶体管，内存用磁芯，使用 FORTRAN、COBOL 等高级语言，应用于数据处理；第 3 代：CPU 用中小规模集成电路（SSI、MSI），内存用 SSI、MSI 的半导体存储器，出现操作系统、数据库管理系统，应用于科学计算、事务处理、分析和工业控制；第 4 代：CPU 用大规模、超大规模集成电路（LSI、VLSI），内存用 LSI、VLSI 的半导体存储器，应用于各个行业和家庭。四种应用模式：集中计算模式（发明至 20 世纪 70 年代，用于公司和部队）、分散计算模式（70 年代，用于家庭）、网络计算模式（90 年代，网络数据传输）、云计算模式（当代）。按内部逻辑结构还可分为 16 位、32 位、64 位机。$kp$, section = '' where id = 25195;
update t_knowledge_point set title = $kp$按性能与用途划分的各类计算机$kp$, content = $kp$巨型计算机（超级计算机）采用并行处理，用于军事科研、气象预报、石油勘探、生物信息处理、飞机设计等领域，我国目前最快的是“神威·太湖之光”。大型计算机为企业、政府的海量数据提供集中的存储、管理和处理，承担主服务器（企业级服务器）的功能，可一二十年不间断运行。服务器是网络中专门为其他计算机提供资源和服务的计算机，需 7×24 小时运行，分为工作组级（家用）、部门级、企业级服务器，浪潮集团是我国最大的服务器制造商；服务器有三种应用方式：作为服务器、作为个人计算机、嵌入式应用。个人计算机也称个人电脑、PC 或微型计算机，因单片微处理器的出现而发展起来，常见形式有台式机、便携机、工作站（多安装 Linux 操作系统）。嵌入式计算机把运算器、控制器、存储器、I/O 控制、接口电路全集成在一块芯片上，即单片机；把微处理器、存储器、I/O 接口等集成在单个芯片上的超大规模集成电路是 SoC（片上系统、系统级芯片），用于数码相机、MP3、手机、汽车、计算机外设等；市场份额最大的是英国 ARM 公司的 ARM 处理器，手机和平板电脑都采用 ARM 技术。$kp$, section = '' where id = 25196;
update t_knowledge_point set title = $kp$信息处理的五个环节$kp$, content = $kp$信息的收集（信息获取）、信息的存储、信息的加工（信息处理）、信息的传递（通信）、信息的施用（展现、显示与控制）。$kp$, section = '' where id = 25197;
update t_knowledge_point set title = $kp$经典计算机的逻辑结构示意$kp$, content = $kp$存储器位于上方；输入设备将数据送入运算器和控制器，运算器和控制器把处理结果送输出设备，并与存储器交换数据。$kp$, section = '' where id = 25199;
update t_knowledge_point set title = $kp$计算机硬件组成：主机与外设$kp$, content = $kp$硬件是计算机系统中所有实际物理装置的总称，如 CPU 芯片、存储器芯片、鼠标、键盘、硬盘；硬件是软件的载体，软硬件缺一不可。CPU 和主存储器构成主机的主体部分，I/O 设备和辅助存储器构成外围设备（外设）。主存储器（内存、主存）存取速度快、容量小、成本高，断电后信息几乎消失（BIOS 中的只读 ROM 除外），属易失性存储器；它存放已经启动的应用程序和需立即处理的数据，CPU 处理的指令和数据直接从内存取得；主存与 CPU 高速连接，按字节编址（每个字节都有地址），是计算机的工作存储器。辅助存储器（外存、辅存）存取速度慢、容量大、成本低，断电后信息仍能保存，属非易失性存储器，长期存放计算机几乎所有的信息，按数据块编址；程序和数据从硬盘调入主存，再送 CPU 运行处理。输入设备把信息以二进制形式送入内存，如键盘、鼠标、触摸屏、麦克风、传感器、条码与磁卡及 IC 卡的扫描器或读卡器、DVD 驱动器等；输出设备把信息送出计算机，输出形式可以是文本、语音、音乐、图像、动画，如显示器、打印机、绘图仪、音响、投影仪。$kp$, section = '' where id = 25200;
update t_knowledge_point set title = $kp$计算机硬件的经典逻辑结构$kp$, content = $kp$计算机硬件基本结构包括运算器、控制器、存储器、输入设备、输出设备，即冯·诺依曼计算机的五大部件；CPU（中央处理器）由控制器和运算器组成。计算机内部采用二进制表示程序和数据。$kp$, section = '' where id = 26691;
update t_knowledge_point set title = $kp$操作系统是用户与硬件的接口$kp$, content = $kp$操作系统是用户和硬件的接口。$kp$, section = '' where id = 27212;
update t_knowledge_point set title = $kp$并发多任务的含义$kp$, content = $kp$并发多任务指操作系统使用 1 个 CPU 同时实现多个任务同时运行，不管是前台任务还是后台任务，都能分配到 CPU 的使用权。$kp$, section = '' where id = 27217;
update t_knowledge_point set title = $kp$多任务的目的$kp$, content = $kp$多任务的目的：提高 CPU 的利用率。$kp$, section = '' where id = 27218;
update t_knowledge_point set title = $kp$高级程序设计语言的移植性$kp$, content = $kp$高级程序设计语言不依赖于硬件，因此移植性好。$kp$, section = '' where id = 27252;
update t_knowledge_point set title = $kp$存储程序控制原理与计算机系统的组成$kp$, content = $kp$“存储程序控制”的计算机工作原理是：程序和数据必须从外存调入内存，再交给 CPU 执行。完整的计算机系统包括硬件系统和软件系统，其中硬件系统又分为主机和外设。$kp$, section = '' where id = 27275;
update t_knowledge_point set title = $kp$计算机辅助系统与计算机分类$kp$, content = $kp$计算机辅助系统包括 CAD（计算机辅助设计）、CAM（计算机辅助制造）、CAI（计算机辅助教学）等。计算机按性能规模可分为巨型机、大型机、服务器、个人计算机、嵌入式计算机。嵌入式计算机为其他设备服务，具有价格便宜、功耗低、实时处理、功能专用单一、结构紧凑、软件固化、不易修改和扩充等特点，其核心是 SoC（片上系统）。近年来流行的平板电脑、智能手机均采用英国 ARM 公司的 ARM 技术 CPU，其指令系统与普通 PC 完全不同，相互不兼容。$kp$, section = '' where id = 27279;
update t_knowledge_point set title = $kp$计算机病毒的破坏范围$kp$, content = $kp$计算机病毒既可以破坏硬件，也可以破坏软件和数据。$kp$, section = '' where id = 27287;
update t_knowledge_point set title = $kp$电子元器件发展的四代$kp$, content = $kp$电子元器件的发展经历了电子管、晶体管、中小规模集成电路、大规模和超大规模集成电路四代，现代计算机属于第四代。$kp$, section = '' where id = 27699;
update t_knowledge_point set title = $kp$第一代计算机（电子管）$kp$, content = $kp$第一代计算机是电子管计算机。$kp$, section = '' where id = 27943;
update t_knowledge_point set title = $kp$第二代计算机（晶体管）$kp$, content = $kp$第二代计算机是晶体管计算机。$kp$, section = '' where id = 27944;
update t_knowledge_point set title = $kp$科学计算的应用举例$kp$, content = $kp$科学计算的典型应用如天气预报。$kp$, section = '' where id = 27945;
update t_knowledge_point set title = $kp$数据处理的应用举例$kp$, content = $kp$数据处理的典型应用如办公自动化、财务管理系统、学籍管理系统等。$kp$, section = '' where id = 27946;
update t_knowledge_point set title = $kp$计算机的五大基本组成部分$kp$, content = $kp$计算机基本组成分为五个部分：运算器、控制器、存储器、输入设备、输出设备，它们通过总线相互连接。$kp$, section = '' where id = 28006;
update t_knowledge_point set title = $kp$硬件增加、减少或更换时的参数登记$kp$, content = $kp$系统增加、减少或更换硬件时，并非所有硬件都需要登记参数，一般登记硬盘和光驱的个数。$kp$, section = '' where id = 28045;
update t_knowledge_point set title = $kp$设备管理与驱动程序$kp$, content = $kp$设备管理指对所有设备的管理，驱动程序是操作系统和硬件之间的接口。$kp$, section = '' where id = 28099;
update t_knowledge_point set title = $kp$不依赖硬件则移植性好$kp$, content = $kp$不依赖于硬件，因此移植性好。$kp$, section = '' where id = 28102;
update t_knowledge_point set title = $kp$资源共享的含义与举例$kp$, content = $kp$资源共享中的资源指硬件、软件、数据或程序。例如：共享网络打印机，浏览网页、下载音乐和视频，使用其他计算机的存储和计算能力。$kp$, section = '' where id = 28104;
update t_knowledge_point set title = $kp$并发多任务技术$kp$, content = $kp$采用“并发多任务”技术：前后台任务都能分配到 CPU 的使用权，可以同时运行。$kp$, section = '' where id = 28259;
update t_knowledge_point set title = $kp$多任务宏观上同时、微观上轮流$kp$, content = $kp$多个任务在宏观上同时运行，在微观上由 CPU 轮流运行。$kp$, section = '' where id = 28260;
update t_knowledge_point set title = $kp$冯·诺依曼的三条计算机设计原理$kp$, content = $kp$冯·诺依曼提出三条计算机设计原理：① 计算机使用二进制；② 现代计算机自动工作的原因是存储程序控制；③ 计算机分为五大基本组成部分：运算器、控制器、存储器、输入设备、输出设备。$kp$, section = '' where id = 28277;
update t_knowledge_point set title = $kp$文本展现的过程$kp$, content = $kp$① 对文本的格式描述进行解释；② 生成文字和图素；③ 传送到显示器或打印的映像（bitmap）。$kp$, section = '' where id = 28389;
update t_knowledge_point set title = $kp$操作系统多任务的含义$kp$, content = $kp$操作系统的多任务指将 CPU 的时间划分成时间片，由一个 CPU 执行多个任务。$kp$, section = '' where id = 28503;
update t_knowledge_point set title = $kp$第一代计算机：电子管计算机$kp$, content = $kp$第 1 代：电子管计算机。$kp$, section = '' where id = 28552;
update t_knowledge_point set title = $kp$第二代计算机：晶体管计算机$kp$, content = $kp$第 2 代：晶体管计算机。$kp$, section = '' where id = 28553;
update t_knowledge_point set title = $kp$计算机按电子元器件划分为四代$kp$, content = $kp$按照电子元器件的不同，计算机被划分为四代，现代计算机属于第四代。$kp$, section = '' where id = 28555;
update t_knowledge_point set title = $kp$硬件抽象层的作用$kp$, content = $kp$硬件抽象层是操作系统与硬件之间的接口，隐藏特定平台硬件的接口细节，保护硬件厂商的知识产权，并使其具有硬件无关性。$kp$, section = '' where id = 28610;
update t_knowledge_point set title = $kp$计算机的组成：硬件与软件$kp$, content = $kp$使用网络可以方便迅速地与其他计算机交换信息。计算机由硬件和软件组成：硬件是物理装置的总称，软件由程序和数据组成。$kp$, section = '' where id = 28629;
update t_knowledge_point set title = $kp$单片计算机$kp$, content = $kp$单片计算机：运算器、控制器、存储器、I/O 控制与接口电路等集成在同一块芯片上的超大规模集成电路。$kp$, section = '' where id = 28631;
update t_knowledge_point set title = $kp$嵌入式计算机$kp$, content = $kp$嵌入式计算机是内嵌在其他设备中的计算机，广泛应用于数码相机、手机和 MP3 等产品中。$kp$, section = '' where id = 28632;
update t_knowledge_point set title = $kp$计算机按服务对象分类$kp$, content = $kp$服务器：服务于其他计算机；个人计算机：服务于个人；嵌入式计算机：服务于其他设备（所有智能设备中都有单片机）。$kp$, section = '' where id = 28668;
update t_knowledge_point set title = $kp$操作系统的四大管理功能$kp$, content = $kp$操作系统共有四大管理：多任务管理（CPU 管理）、存储管理（对内存的管理）、文件管理、设备管理。$kp$, section = '' where id = 28706;
update t_knowledge_point set title = $kp$多任务处理的机制与前后台任务$kp$, content = $kp$多任务处理指多个任务在计算机中同时运行，每个任务都可以使用包括 CPU 在内的几乎全部软硬件资源。任务是指装入内存并启动执行的一个程序。为支持多任务处理，操作系统中的处理器调度程序负责把 CPU 时间分配给各个任务，使多个任务“同时”执行。调度程序采用按时间片轮转的方法，每个任务轮流得到一个时间片的 CPU 时间，时间片结束后再把 CPU 交给下一个任务，因此一个 CPU 就可以“同时”执行多个任务。时间片到后，无论程序执行到何处，Windows 都强制它让出 CPU，这称为抢占式多任务；Win3.1 采用非抢占式多任务，Windows 95 及以后的系统都是抢占式多任务。目的：提高 CPU 的利用率。注意：单核 CPU 在任何时刻只有一个任务在执行，双核则任一时刻真正有 2 个任务在执行。Windows 操作系统本身也与应用程序一起参与 CPU 轮转，因此即使只有一个应用程序，同样要进行 CPU 轮转，不可能一直占用 CPU。借助“任务管理器”可以查看有哪些任务同时在运行。能接受用户输入（击键或按鼠标）的窗口只能有一个，称为活动窗口，它所对应的任务称为前台任务；除前台任务外，其他任务均为后台任务。前台任务对应的活动窗口位于其他窗口的前面，其标题栏颜色比非活动窗口更深（深蓝色）；两者的共同点是都在计算机中运行。为了向某个后台任务输入信息，必须切换窗口（单击要激活的后台任务窗口的任何部位，或单击任务栏中对应的任务按钮）。无论前台任务还是后台任务，都能得到 CPU 的时间片轮转、得到 CPU 的执行，不能认为后台任务得不到 CPU 的执行。$kp$, section = '' where id = 28707;
update t_knowledge_point set title = $kp$操作系统的作用$kp$, content = $kp$操作系统是计算机系统的基础和核心，管理计算机所有的软、硬件资源，提供图形用户界面（GUI），并提供高效率的开发平台。$kp$, section = '' where id = 28758;
update t_knowledge_point set title = $kp$操作系统的四大功能$kp$, content = $kp$操作系统的功能主要有四个：处理器管理（宏观上同时执行、微观上单一执行，采用时间片轮转的处理策略）；存储管理（采用“虚拟存储技术”，虚拟存储器由物理内存和硬盘上的页面文件组成，使用 LRU 算法）；文件管理（多级层次式树状结构）；设备管理（通过“我的电脑”快捷菜单“属性”中的“设备管理器”进行）。$kp$, section = '' where id = 28759;
update t_knowledge_point set title = $kp$并行执行的含义$kp$, content = $kp$“并行”是指在含有多个 CPU 的计算机中，多个程序在不同的 CPU 上同时获得执行的机制。$kp$, section = '' where id = 28762;
update t_knowledge_point set title = $kp$计算机病毒的定义$kp$, content = $kp$计算机病毒是人为蓄意编制的一种具有寄生性和自我复制能力的计算机程序，可以造成计算机硬件的损坏。$kp$, section = '' where id = 28763;
update t_knowledge_point set title = $kp$计算机的工作原理$kp$, content = $kp$计算机由 CPU、内存、外存和输入、输出设备组成。开机后会将有可能用到的指令和数据预先读入缓存，缓存中的数据是内存中部分数据的副本；由控制器读取存储器中的指令并放入寄存器。CPU 可以直接访问缓存和内存，不能直接访问外存，外存中的数据必须经过内存才能传给 CPU。指令是计算机中进行程序控制的最小单位，用二进制表示，包含操作码和操作数。指令计数器存放当前正在执行的指令的地址，当前指令执行完毕后要修改指令计数器，以决定下一条指令的地址。不同 CPU 包含的指令可以不同，但要保持向下兼容。$kp$, section = '' where id = 28766;
update t_knowledge_point set title = $kp$计算机的组成结构$kp$, content = $kp$计算机由硬件和软件组成。硬件分为主机和外设：主机包括 CPU、内存、主板；外设包括电源、外存、输入和输出设备。按冯·诺依曼体系，硬件由运算器（整型和浮点运算）、控制器、存储器（内存和外存）、输入、输出（I/O 控制器）组成。软件分为系统软件和应用软件：系统软件包括操作系统、语言处理程序、数据库管理系统；应用软件如计算机管理和服务程序。$kp$, section = '' where id = 28774;
update t_knowledge_point set title = $kp$对话框的组成与操作$kp$, content = $kp$对话框由标题栏（名称、帮助按钮和关闭按钮）、选项卡、文本框、下拉列表、列表框、单选框、复选框、按钮组成。关闭：单击关闭按钮、按 Alt+F4、按 Esc、单击确定或取消按钮；移动：用鼠标拖动标题栏；切换选项卡：Ctrl+Tab。总结：窗口打开后会显示在任务栏上，对话框不显示；窗口可以缩放、最大化、最小化，对话框不能缩放。$kp$, section = '' where id = 28783;
update t_knowledge_point set title = $kp$冯·诺依曼的三条计算机设计原理$kp$, content = $kp$冯·诺依曼提出三条计算机设计原理：① 计算机使用二进制；② 现代计算机自动工作的原因是存储程序控制；③ 计算机分为五大基本组成部分：运算器、控制器、存储器、输入设备、输出设备。$kp$, section = '' where id = 28837;
update t_knowledge_point set title = $kp$实用程序包括哪些$kp$, content = $kp$实用程序包括磁盘扫描程序、磁盘清理程序、磁盘碎片整理程序、备份程序、杀毒软件、基本输入输出系统（BIOS）、防火墙等。$kp$, section = '' where id = 28873;
update t_knowledge_point set title = $kp$多任务强调一个 CPU 运行多个任务$kp$, content = $kp$多任务强调的是一个 CPU 运行一个用户的多个任务，比如一边听歌一边浏览网页，都是由一个 CPU 实现的。$kp$, section = '' where id = 28878;
update t_knowledge_point set title = $kp$计算机系统的组成$kp$, content = $kp$计算机系统由硬件系统和软件系统组成。硬件包括运算器、控制器、存储器、输入设备、输出设备，遵循冯·诺依曼提出的“存储程序控制”原理。软件包括系统软件和应用软件，应用软件以系统软件为基础。$kp$, section = '' where id = 28899;
update t_knowledge_point set title = $kp$巨型计算机$kp$, content = $kp$巨型计算机采用大规模并行处理（为提高计算机处理能力配置多个 CPU）的体系结构，运算速度达到每秒数万亿次以上。$kp$, section = '' where id = 28945;
update t_knowledge_point set title = $kp$程序设计语言的分类与特点$kp$, content = $kp$机器语言：就是计算机的指令系统，每条指令都是二进制。特点：执行效率高，移植性差，编写效率低。汇编语言：用助记符号代替二进制，面向机器，难以开发大型程序。高级语言：接近人们使用的自然语言（主要是英语）。特点：执行效率低，移植性高，编写效率高。$kp$, section = '' where id = 28990;
update t_knowledge_point set title = $kp$文件的命名规则$kp$, content = $kp$文件由文件名和类型名（扩展名）组成。常见类型名：EXE、COM、BAT、TXT、MP3、RAR。文件名最长 255 个字符或 127 个汉字，不能出现下列字符：\ / | “ * ? :$kp$, section = '' where id = 29581;
update t_knowledge_point set title = $kp$计算机按性能、用途和价格分类$kp$, content = $kp$按计算机的性能、用途和价格可分为四大类：巨型机、大型机、小型机、个人计算机（如工作站）。$kp$, section = '' where id = 30139;
update t_knowledge_point set title = $kp$机器人探索虚拟世界的操作流程$kp$, content = $kp$用户使用编辑器（Editor）编写文件以设置想要模拟的环境，将文件导入系统（Load File），从而在仿真系统中建立虚拟世界（Setup World）。机器人在虚拟世界中的行为也在文件中定义，据此建立机器人的探索行为程序（Setup Program）。机器人探索时（Run Program）有两种运行模式：① 自动控制（Run），事先编排好机器人的动作序列（指令），执行指令使机器人连续动作，若干条指令构成机器人的指令集（Instruction Set）；② 单步控制（Step），是自动控制方式的一种特殊形式，只执行指定指令中的一个动作。$kp$, section = '' where id = 31949;
update t_knowledge_point set title = $kp$软件的下载与覆盖安装更新$kp$, content = $kp$有些软件可以手动到官网或其他网站下载最新版，用新版本安装包覆盖安装，更新成想要的版本。已安装过该软件时，安装程序一般会检测出来并提示安装方式：修改（Modify，选择要安装的功能）、修复（Repair，修复缺失或损坏的文件、快捷方式和注册表项）、删除（Remove）。$kp$, section = '' where id = 31951;
update t_knowledge_point set title = $kp$C 语言常量、变量的命名规则与数据类型$kp$, content = $kp$编译系统将大写字母和小写字母视为不同字符，习惯上符号常量用大写；变量名长度建议不超过 8 个字符，选择变量名和其他标识符应做到“见名知意”，即选用有含义的英文单词或其缩写；所有用到的变量都必须先定义后使用，即强制类型定义。整型数据在内存中以二进制形式存放，采用补码表示；16 位 int 型变量只能容纳 -32768～32767 范围内的数，超出则发生溢出；值在 -32768～32767 范围内的整数认为是 int 型，可赋给 int 型和 long int 型变量；整常量后加字母 u 或 U 表示 unsigned int 型（如 12345u），加字母 l 或 L 表示 long int 型常量。浮点型数据一般占 4 个字节（32 位），与整型不同，按指数形式存储；浮点型变量分为单精度 float、双精度 double 和长双精度 long double 三类。$kp$, section = '' where id = 32236;
update t_knowledge_point set title = $kp$编译过程与常用数制的表示$kp$, content = $kp$把高级语言源程序翻译成机器语言目标程序的过程叫编译。源程序后缀为 .c，目标文件后缀为 .obj，可执行文件后缀为 .exe。常用数制：十进制用 0～9；二进制用 0、1，前缀为 0b（如 0b11010）；八进制用 0～7，前缀为 0（如 05124）；十六进制用 0～9、A～F，前缀为 0x（如 0x5d12）。$kp$, section = '' where id = 32256;

do $$
begin
  if (select count(*) from t_knowledge_point where id in (21881,21883,21884,22142,22155,22189,22201,22204,22209,22218,22220,22290,22492,22541,24136,25138,25193,25194,25195,25196,25197,25199,25200,26691,27212,27217,27218,27252,27275,27279,27287,27699,27943,27944,27945,27946,28006,28045,28099,28102,28104,28259,28260,28277,28389,28503,28552,28553,28555,28610,28629,28631,28632,28668,28706,28707,28758,28759,28762,28763,28766,28774,28783,28837,28873,28878,28899,28945,28990,29581,30139,31949,31951,32236,32256) and not deleted) <> 75 then
